const API_OPERACIONES = '/joyaexpress-system/backend/api/operaciones.php';
const API_FLUJO = '/joyaexpress-system/backend/api/flujo.php';
const fetchOriginalJoya = window.fetch.bind(window);
let csrfTokenJoya = null;
async function obtenerCsrfJoya() {
    if (csrfTokenJoya) return csrfTokenJoya;
    const r = await fetchOriginalJoya('/joyaexpress-system/backend/api/auth.php?accion=csrf', {credentials:'same-origin',cache:'no-store'});
    const d = await leerRespuestaAuth(r);
    if (!d.exito || !d.datos || !d.datos.token) {
        throw new Error(d.mensaje || 'No se pudo iniciar la sesión segura.');
    }
    csrfTokenJoya = d.datos.token; return csrfTokenJoya;
}
window.fetch = async function(recurso, opciones={}) {
    const metodo=(opciones.method||'GET').toUpperCase();
    if (!['GET','HEAD','OPTIONS'].includes(metodo)) {
        const headers=new Headers(opciones.headers||{});
        headers.set('X-CSRF-Token', await obtenerCsrfJoya());
        opciones={...opciones,headers,credentials:opciones.credentials||'same-origin'};
    }
    let respuesta=await fetchOriginalJoya(recurso,opciones);
    if(respuesta.status===403&&!['GET','HEAD','OPTIONS'].includes(metodo)){
        csrfTokenJoya=null;const headers=new Headers(opciones.headers||{});headers.set('X-CSRF-Token',await obtenerCsrfJoya());respuesta=await fetchOriginalJoya(recurso,{...opciones,headers});
    }
    if(String(recurso).includes('accion=logout'))csrfTokenJoya=null;
    return respuesta;
};
let moduloOperacionesInicializado = false;

function escaparHtml(valor) {
    return String(valor ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
}
async function apiOperaciones(accion, opciones = {}) {
    const response = await fetch(`${API_OPERACIONES}?accion=${accion}`, { cache:'no-store', credentials:'same-origin', ...opciones });
    const texto = await response.text();
    let data; try { data = JSON.parse(texto); } catch { throw new Error('Respuesta inválida del servidor'); }
    if (!data.exito) throw new Error(data.mensaje || 'Operación fallida');
    return data.datos;
}
async function apiFlujo(accion, opciones={}) {
    const r=await fetch(`${API_FLUJO}?accion=${accion}`,{cache:'no-store',credentials:'same-origin',...opciones});
    const texto=await r.text();let d;try{d=JSON.parse(texto);}catch{throw new Error('Respuesta inválida del servidor');}
    if(!d.exito){const e=new Error(d.mensaje||'Operación fallida');e.datos=d.datos;e.status=r.status;throw e;}return d.datos;
}
function opcionPaises(valor='') { return ['USA','Guatemala','Honduras'].map(p=>`<option ${p===valor?'selected':''}>${p}</option>`).join(''); }
function agregarMenu(nombre, icono, seccion) {
    const lista=document.querySelector('#navbarNav .navbar-nav'); const usuario=lista.querySelector('.dropdown');
    const iconoHtml=icono==='icono-retiro'
        ? '<svg class="menu-icon-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 10v10h16V10M3 4h18l-2 6H5L3 4Zm6 16v-6h6v6"/></svg>'
        : `<i class="fas ${icono}"></i>`;
    const li=document.createElement('li');li.className='nav-item modulo-ampliado';li.innerHTML=`<a class="nav-link" href="#" onclick="mostrarSeccion('${seccion}');cargarSeccionAmpliada('${seccion}')">${iconoHtml} ${nombre}</a>`;lista.insertBefore(li,usuario);
}
function agregarSeccion(id, html) { const cont=document.querySelector('#dashboard-container > .container-fluid');const div=document.createElement('div');div.id=`seccion-${id}`;div.className='seccion';div.style.display='none';div.innerHTML=html;cont.appendChild(div); }

function inicializarModuloOperaciones() {
    if (moduloOperacionesInicializado || !usuarioActual) return;
    moduloOperacionesInicializado=true;
    agregarMenu('Incidencias','fa-triangle-exclamation','incidencias');
    if(tieneRol(['admin','supervisor','bodega'])){agregarMenu('Recepción destino','fa-clipboard-check','recepcion-destino');agregarSeccion('recepcion-destino',plantillaRecepcionDestino());}
    if(tieneRol(['admin','supervisor','bodega','entrega'])){agregarMenu('Retiros','icono-retiro','retiros');agregarSeccion('retiros',plantillaRetiros());}
    agregarSeccion('incidencias',`<h2><i class="fas fa-triangle-exclamation"></i> Gestión de incidencias</h2><div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" onclick="abrirNuevaIncidencia()">Nueva incidencia</button></div><div id="lista-incidencias">Cargando...</div>`);
    if (tieneRol(['admin','supervisor','bodega','entrega'])) { agregarMenu('Entregas','fa-truck','entregas'); agregarSeccion('entregas',plantillaEntregas()); }
    if (tieneRol(['admin','supervisor'])) { agregarMenu('Control','fa-gears','control'); agregarSeccion('control',plantillaControl()); document.querySelector('#panel-tarifas .btn-primary')?.insertAdjacentHTML('afterend',' <button class="btn btn-outline-secondary my-3" onclick="verHistorialTarifas()">Historial</button>'); }
    if(tieneRol(['admin','supervisor'])){agregarMenu('Notificaciones','fa-envelope','notificaciones');agregarSeccion('notificaciones',plantillaNotificaciones());}
    if (tieneRol(['admin'])) { agregarMenu('Usuarios','fa-users','usuarios'); agregarSeccion('usuarios',plantillaUsuarios()); }
    if (tieneRol(['admin'])) { agregarMenu('Sucursales','fa-building','sucursales'); agregarSeccion('sucursales','<h2><i class="fas fa-building"></i> Sucursales</h2><button class="btn btn-primary mb-3" onclick="editarSucursal()">Nueva sucursal</button><div id="lista-sucursales"></div>'); }
    const reportes=document.getElementById('seccion-reportes');if(reportes) reportes.insertAdjacentHTML('beforeend','<div id="reportes-avanzados" class="mt-4"></div>');
    const dashboard=document.getElementById('seccion-dashboard');dashboard.insertAdjacentHTML('afterbegin','<div id="aviso-contingencia" class="alert alert-warning" style="display:none"><strong>Modo contingencia:</strong> <span id="cantidad-pendientes">0</span> registros pendientes. <button class="btn btn-sm btn-warning ms-2" onclick="sincronizarPendientes()">Sincronizar</button></div>');actualizarAvisoPendientes();prepararSucursalesRetiro();
}
function cargarSeccionAmpliada(seccion) {
    if(seccion==='incidencias') cargarIncidencias();
    if(seccion==='entregas') cargarRutas();
    if(seccion==='control') { cargarTarifas(); cargarBitacora(); cargarReportesAvanzados(); }
    if(seccion==='usuarios') cargarUsuarios();
    if(seccion==='sucursales') cargarSucursales();
    if(seccion==='recepcion-destino') cargarRecepcionesDestino();
    if(seccion==='retiros') cargarRetiros();
    if(seccion==='notificaciones') cargarNotificaciones();
}

async function calcularTarifaFormulario() {
    const f=document.getElementById('form-nueva-encomienda');let peso=Number(f.elements.peso_kg.value);if(f.elements.unidad_peso.value==='lb')peso*=0.453592;
    try {
        const d=await apiOperaciones('calcular_tarifa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pais_origen:f.elements.remitente_pais.value,pais_destino:f.elements.destinatario_pais.value,peso_kg:peso})});
        f.elements.costo_quetzales.value=Number(d.total).toFixed(2);
        f.elements.tarifa_id.value=d.tarifa.id;
        document.getElementById('peso-normalizado').value=`${peso.toFixed(2)} kg`;
        document.getElementById('tarifa-aplicada').value=`#${d.tarifa.id}: Q${Number(d.tarifa.costo_base_quetzales).toFixed(2)} base + Q${Number(d.tarifa.costo_por_kg_quetzales).toFixed(2)} por kg`;
        mostrarAlerta('success',`Tarifa calculada: Q${Number(d.total).toFixed(2)}`);
    } catch(e){mostrarAlerta('warning',e.message);}
}
function leerArchivo(input) { return new Promise((resolve,reject)=>{const file=input.files[0];if(!file)return resolve(null);const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);}); }

function abrirInspeccion(encomiendaId) {
    const html=`<form id="form-inspeccion"><div class="form-check"><input class="form-check-input" type="checkbox" name="contenido_coincide" id="rev1"><label for="rev1">Contenido coincide con lo declarado</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="empaque_adecuado" id="rev2"><label for="rev2">Empaque adecuado</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="articulo_restringido" id="rev3"><label for="rev3">Artículo restringido</label></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="requiere_aprobacion" id="rev4"><label for="rev4">Requiere aprobación</label></div><textarea class="form-control mb-3" name="observaciones" placeholder="Observaciones"></textarea><input class="form-control mb-3" type="file" name="foto" accept="image/*"><button class="btn btn-primary" type="submit">Guardar revisión</button></form>`;
    mostrarModalDetalles('Inspección de encomienda',html);document.getElementById('form-inspeccion').onsubmit=async e=>{e.preventDefault();const f=e.target;try{const foto=await leerArchivo(f.elements.foto);const d={encomienda_id:encomiendaId,contenido_coincide:f.elements.contenido_coincide.checked,empaque_adecuado:f.elements.empaque_adecuado.checked,articulo_restringido:f.elements.articulo_restringido.checked,requiere_aprobacion:f.elements.requiere_aprobacion.checked,observaciones:f.elements.observaciones.value,foto};await apiOperaciones('revisar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();mostrarAlerta('success','Revisión registrada');buscarEncomiendas();}catch(err){mostrarAlerta('danger',err.message);}};
}

async function abrirNuevaIncidencia(encomiendaId=null) {
    try { const res=await fetch(`${API_URL}/encomiendas.php?accion=buscar`,{cache:'no-store'});const data=await res.json();const opciones=(data.datos||[]).map(e=>`<option value="${e.id}" ${e.id==encomiendaId?'selected':''}>${e.tracking_id} - ${escaparHtml(e.destinatario_nombre)}</option>`).join('');
        const html=`<form id="form-incidencia"><select class="form-select mb-3" name="encomienda_id" required>${opciones}</select><select class="form-select mb-3" name="tipo"><option value="dano">Daño</option><option value="extravio">Extravío</option><option value="datos_incorrectos">Datos incorrectos</option><option value="sobrepeso">Sobrepeso</option><option value="otro">Otro</option></select><textarea class="form-control mb-3" name="detalle" required placeholder="Detalle"></textarea><input class="form-control mb-3" type="file" name="foto" accept="image/*"><button class="btn btn-danger">Registrar incidencia</button></form>`;mostrarModalDetalles('Nueva incidencia',html);
        document.getElementById('form-incidencia').onsubmit=async e=>{e.preventDefault();const f=e.target;try{await apiOperaciones('incidencia_crear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({encomienda_id:Number(f.elements.encomienda_id.value),tipo:f.elements.tipo.value,detalle:f.elements.detalle.value,foto:await leerArchivo(f.elements.foto)})});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();mostrarAlerta('success','Incidencia registrada');cargarIncidencias();buscarEncomiendas();}catch(err){mostrarAlerta('danger',err.message);}};
    } catch(e){mostrarAlerta('danger',e.message);}
}
async function cargarIncidencias(){try{const datos=await apiOperaciones('incidencias_listar');document.getElementById('lista-incidencias').innerHTML=datos.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Tracking</th><th>Tipo</th><th>Detalle</th><th>Estado</th><th>Responsable</th><th>Acción</th></tr></thead><tbody>${datos.map(i=>`<tr><td>${i.tracking_id}</td><td>${i.tipo}</td><td>${escaparHtml(i.detalle)}</td><td>${i.estado}</td><td>${i.responsable_nombre||''}</td><td>${tieneRol(['admin','supervisor','bodega'])?`<button class="btn btn-sm btn-primary" onclick="resolverIncidencia(${i.id})">Gestionar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="alert alert-info">No hay incidencias.</div>';}catch(e){document.getElementById('lista-incidencias').innerHTML=`<div class="alert alert-danger">${e.message}</div>`;}}
function resolverIncidencia(id){const html=`<form id="resolver-inc"><select class="form-select mb-3" name="estado"><option value="en_revision">En revisión</option><option value="resuelta">Resuelta</option><option value="cerrada">Cerrada</option></select><textarea class="form-control mb-3" name="resolucion" required placeholder="Resolución"></textarea><button class="btn btn-primary">Guardar</button></form>`;mostrarModalDetalles('Gestionar incidencia',html);document.getElementById('resolver-inc').onsubmit=async e=>{e.preventDefault();try{await apiOperaciones('incidencia_actualizar',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,estado:e.target.elements.estado.value,resolucion:e.target.elements.resolucion.value})});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();cargarIncidencias();mostrarAlerta('success','Incidencia actualizada');}catch(err){mostrarAlerta('danger',err.message);}};}

function plantillaEntregas(){return `<h2><i class="fas fa-truck"></i> Rutas y entregas</h2><div class="card mb-4"><div class="card-body"><h5>Nueva ruta</h5><form id="form-ruta" class="row g-2"><div class="col-md-3"><input class="form-control" name="nombre_ruta" placeholder="Nombre de ruta" required></div><div class="col-md-2"><select class="form-select" name="pais">${opcionPaises()}</select></div><div class="col-md-3"><select class="form-select" name="mensajero_id" id="ruta-mensajero" required></select></div><div class="col-md-2"><input class="form-control" type="date" name="fecha_ruta" required></div><div class="col-md-2"><button class="btn btn-success w-100">Crear</button></div></form></div></div><div id="lista-rutas"></div>`;}
async function cargarRutas(){try{const [rutas,catalogos]=await Promise.all([apiOperaciones('rutas_listar'),apiOperaciones('catalogos')]);document.getElementById('ruta-mensajero').innerHTML=catalogos.mensajeros.map(m=>`<option value="${m.id}">${m.nombre}</option>`).join('');const f=document.getElementById('form-ruta');f.onsubmit=guardarRuta;document.getElementById('lista-rutas').innerHTML=rutas.length?`<table class="table"><thead><tr><th>Código</th><th>Ruta</th><th>Mensajero</th><th>Fecha</th><th>Estado</th><th>Paquetes</th></tr></thead><tbody>${rutas.map(r=>`<tr><td>${r.codigo}</td><td>${r.nombre_ruta}</td><td>${r.mensajero_nombre}</td><td>${r.fecha_ruta}</td><td>${r.estado}</td><td>${r.paquetes}</td></tr>`).join('')}</tbody></table>`:'<div class="alert alert-info">No hay rutas.</div>';}catch(e){mostrarAlerta('danger',e.message);}}
async function guardarRuta(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.mensajero_id=Number(d.mensajero_id);try{await apiOperaciones('ruta_crear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});e.target.reset();cargarRutas();mostrarAlerta('success','Ruta creada');}catch(err){mostrarAlerta('danger',err.message);}}
async function asignarARuta(encomiendaId){try{const rutas=await apiOperaciones('rutas_listar');const opciones=rutas.filter(r=>r.estado!=='finalizada'&&r.estado!=='cancelada').map(r=>`<option value="${r.id}">${r.codigo} - ${r.nombre_ruta}</option>`).join('');if(!opciones)throw new Error('No hay rutas disponibles');mostrarModalDetalles('Asignar a ruta',`<select id="ruta-seleccion" class="form-select mb-3">${opciones}</select><button class="btn btn-primary" onclick="confirmarAsignacionRuta(${encomiendaId})">Asignar</button>`);}catch(e){mostrarAlerta('warning',e.message);}}
async function confirmarAsignacionRuta(encomiendaId){try{await apiOperaciones('ruta_asignar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ruta_id:Number(document.getElementById('ruta-seleccion').value),encomienda_id:encomiendaId})});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();buscarEncomiendas();mostrarAlerta('success','Asignada a ruta');}catch(e){mostrarAlerta('danger',e.message);}}
function abrirConfirmarEntrega(encomiendaId,tipoEntrega){const html=`<form id="form-entrega"><input class="form-control mb-3" name="receptor_nombre" required placeholder="Nombre de quien recibe"><input class="form-control mb-3" name="documento_receptor" placeholder="Documento"><textarea class="form-control mb-3" name="observaciones" placeholder="Observaciones"></textarea><label>Foto de evidencia</label><input class="form-control mb-3" type="file" name="foto" accept="image/*"><label>Firma (imagen)</label><input class="form-control mb-3" type="file" name="firma" accept="image/*"><button class="btn btn-success">Confirmar entrega</button></form>`;mostrarModalDetalles('Evidencia de entrega',html);document.getElementById('form-entrega').onsubmit=async e=>{e.preventDefault();const f=e.target;try{await apiOperaciones('entrega_confirmar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({encomienda_id:encomiendaId,tipo:tipoEntrega,receptor_nombre:f.elements.receptor_nombre.value,documento_receptor:f.elements.documento_receptor.value,observaciones:f.elements.observaciones.value,foto:await leerArchivo(f.elements.foto),firma:await leerArchivo(f.elements.firma)})});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();buscarEncomiendas();cargarEstadisticas();mostrarAlerta('success','Entrega confirmada');}catch(err){mostrarAlerta('danger',err.message);}};}

function plantillaUsuarios(){return `<h2><i class="fas fa-users"></i> Usuarios y roles</h2><div class="d-flex justify-content-end mb-3"><button class="btn btn-primary" onclick="editarUsuario()">Nuevo usuario</button></div><div id="lista-usuarios"></div>`;}
async function cargarUsuarios(){try{const datos=await apiOperaciones('usuarios_listar');document.getElementById('lista-usuarios').innerHTML=`<table class="table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Sucursal</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${datos.map(u=>`<tr><td>${escaparHtml(u.nombre)}</td><td>${u.email}</td><td>${u.rol}</td><td>${escaparHtml(u.sucursal)}</td><td>${u.estado}</td><td><button class="btn btn-sm btn-primary" onclick='editarUsuario(${JSON.stringify(u)})'>Editar</button> <button class="btn btn-sm btn-secondary" onclick="cambiarClaveUsuario(${u.id})">Clave</button></td></tr>`).join('')}</tbody></table>`;}catch(e){mostrarAlerta('danger',e.message);}}
function editarUsuario(u=null){const x=u||{};const html=`<form id="form-usuario"><input type="hidden" name="id" value="${x.id||''}"><input class="form-control mb-2" name="nombre" required placeholder="Nombre" value="${escaparHtml(x.nombre||'')}"><input class="form-control mb-2" type="email" name="email" required placeholder="Email" value="${escaparHtml(x.email||'')}"><select class="form-select mb-2" name="rol">${['admin','supervisor','bodega','recepcion','entrega'].map(r=>`<option ${r===x.rol?'selected':''}>${r}</option>`)}</select><input class="form-control mb-2" name="sucursal" required placeholder="Sucursal" value="${escaparHtml(x.sucursal||'')}">${u?'':`<input class="form-control mb-2" type="password" name="password" minlength="8" required placeholder="Contraseña inicial">`}<select class="form-select mb-3" name="estado"><option value="activo">Activo</option><option value="inactivo" ${x.estado==='inactivo'?'selected':''}>Inactivo</option><option value="bloqueado" ${x.estado==='bloqueado'?'selected':''}>Bloqueado</option></select><button class="btn btn-primary">Guardar</button></form>`;mostrarModalDetalles(u?'Editar usuario':'Nuevo usuario',html);document.getElementById('form-usuario').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.id=Number(d.id||0);try{await apiOperaciones('usuario_guardar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();cargarUsuarios();mostrarAlerta('success','Usuario guardado');}catch(err){mostrarAlerta('danger',err.message);}};}
async function cambiarClaveUsuario(id){const password=prompt('Nueva contraseña (mínimo 8 caracteres):');if(password===null)return;try{await apiOperaciones('usuario_clave',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,password})});mostrarAlerta('success','Contraseña restablecida');}catch(e){mostrarAlerta('danger',e.message);}}

function plantillaControl(){return `<h2><i class="fas fa-gears"></i> Control administrativo</h2><ul class="nav nav-tabs"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#panel-tarifas">Tarifas</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#panel-auditoria">Auditoría</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#panel-reportes">Reportes</button></li></ul><div class="tab-content"><div class="tab-pane fade show active" id="panel-tarifas"><button class="btn btn-primary my-3" onclick="editarTarifa()">Nueva tarifa</button><div id="lista-tarifas"></div></div><div class="tab-pane fade" id="panel-auditoria"><div id="lista-bitacora" class="mt-3"></div></div><div class="tab-pane fade" id="panel-reportes"><div id="control-reportes" class="mt-3"></div></div></div>`;}
async function cargarTarifas(){try{const datos=await apiOperaciones('tarifas_listar');document.getElementById('lista-tarifas').innerHTML=`<table class="table"><thead><tr><th>Ruta</th><th>Rango kg</th><th>Base</th><th>Por kg</th><th>Activa</th><th></th></tr></thead><tbody>${datos.map(t=>`<tr><td>${t.pais_origen} → ${t.pais_destino}</td><td>${t.peso_desde_kg}–${t.peso_hasta_kg}</td><td>Q${t.costo_base_quetzales}</td><td>Q${t.costo_por_kg_quetzales}</td><td>${Number(t.activa)?'Sí':'No'}</td><td><button class="btn btn-sm btn-primary" onclick='editarTarifa(${JSON.stringify(t)})'>Editar</button></td></tr>`).join('')}</tbody></table>`;}catch(e){mostrarAlerta('danger',e.message);}}
async function verHistorialTarifas(){try{const d=await apiOperaciones('tarifas_historial');mostrarModalDetalles('Historial de tarifas',`<table class="table table-sm"><thead><tr><th>Fecha</th><th>Usuario</th><th>Tarifa</th><th>Cambio</th></tr></thead><tbody>${d.map(x=>`<tr><td>${x.fecha_accion}</td><td>${x.usuario_nombre||''}</td><td>#${x.entidad_id}</td><td><small>${escaparHtml(x.valor_nuevo||'')}</small></td></tr>`).join('')}</tbody></table>`);}catch(e){mostrarAlerta('danger',e.message);}}
function editarTarifa(t=null){const x=t||{};const html=`<form id="form-tarifa"><input type="hidden" name="id" value="${x.id||''}"><div class="row g-2"><div class="col-6"><label>Origen</label><select class="form-select" name="pais_origen">${opcionPaises(x.pais_origen)}</select></div><div class="col-6"><label>Destino</label><select class="form-select" name="pais_destino">${opcionPaises(x.pais_destino)}</select></div><div class="col-6"><label>Desde kg</label><input class="form-control" type="number" step=".01" name="peso_desde_kg" value="${x.peso_desde_kg||0}"></div><div class="col-6"><label>Hasta kg</label><input class="form-control" type="number" step=".01" name="peso_hasta_kg" value="${x.peso_hasta_kg||10}"></div><div class="col-6"><label>Costo base</label><input class="form-control" type="number" step=".01" name="costo_base_quetzales" value="${x.costo_base_quetzales||0}"></div><div class="col-6"><label>Costo por kg</label><input class="form-control" type="number" step=".01" name="costo_por_kg_quetzales" value="${x.costo_por_kg_quetzales||0}"></div></div><div class="form-check my-3"><input class="form-check-input" type="checkbox" name="activa" ${x.activa===undefined||Number(x.activa)?'checked':''}><label>Activa</label></div><button class="btn btn-primary">Guardar</button></form>`;mostrarModalDetalles('Tarifa',html);document.getElementById('form-tarifa').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));['id','peso_desde_kg','peso_hasta_kg','costo_base_quetzales','costo_por_kg_quetzales'].forEach(k=>d[k]=Number(d[k]||0));d.activa=f.elements.activa.checked;try{await apiOperaciones('tarifa_guardar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();cargarTarifas();mostrarAlerta('success','Tarifa guardada');}catch(err){mostrarAlerta('danger',err.message);}};}
async function cargarBitacora(){try{const datos=await apiOperaciones('bitacora');document.getElementById('lista-bitacora').innerHTML=`<div class="table-responsive"><table class="table table-sm"><thead><tr><th>Fecha</th><th>Usuario</th><th>Entidad</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${datos.map(b=>`<tr><td>${b.fecha_accion}</td><td>${b.usuario_nombre||'Sistema'}</td><td>${b.entidad} #${b.entidad_id||''}</td><td>${b.accion}</td><td>${escaparHtml(b.detalles||'')}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){mostrarAlerta('danger',e.message);}}
async function cargarReportesAvanzados(){try{const d=await apiOperaciones('reportes');const tabla=(titulo,filas,columnas)=>`<div class="card mb-3"><div class="card-body"><h5>${titulo}</h5><table class="table table-sm"><thead><tr>${columnas.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${filas.map(f=>`<tr>${columnas.map(c=>`<td>${f[c[0]]??0}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;const html=tabla('Encomiendas por sucursal',d.porSucursal,[['sucursal','Sucursal'],['cantidad','Cantidad']])+tabla('Productividad diaria',d.productividad,[['nombre','Empleado'],['fecha','Fecha'],['cantidad','Paquetes']])+tabla('Incidencias por tipo',d.incidencias,[['tipo','Tipo'],['cantidad','Cantidad']])+tabla('Ingresos estimados por ruta',d.ingresos,[['remitente_pais','Origen'],['destinatario_pais','Destino'],['envios','Envíos'],['ingresos','Ingresos Q']])+tabla('Maletas por destino',d.maletas,[['pais_destino','Destino'],['cantidad','Cantidad'],['peso_promedio','Peso promedio']]);document.getElementById('control-reportes').innerHTML=html;const x=document.getElementById('reportes-avanzados');if(x)x.innerHTML=html;}catch(e){const x=document.getElementById('control-reportes');if(x)x.innerHTML=`<div class="alert alert-danger">${e.message}</div>`;}}

function imprimirEtiqueta(encomienda){const w=window.open('','_blank','width=600,height=700');w.document.write(`<html><head><title>Etiqueta ${encomienda.tracking_id}</title><style>body{font-family:Arial;text-align:center;padding:25px}.etiqueta{border:3px solid #000;padding:20px}#qr{margin:20px auto;width:200px}table{width:100%;text-align:left}</style></head><body><div class="etiqueta"><h1>JoyaExpress</h1><div id="qr"></div><h2>${encomienda.tracking_id}</h2><table><tr><th>Destino</th><td>${escaparHtml(encomienda.destinatario_nombre)} — ${encomienda.destinatario_pais}</td></tr><tr><th>Peso</th><td>${encomienda.peso_kg} kg</td></tr><tr><th>Contenido</th><td>${escaparHtml(encomienda.descripcion_items)}</td></tr></table></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><script>new QRCode(document.getElementById('qr'),{text:'${encomienda.tracking_id}',width:200,height:200});setTimeout(()=>window.print(),500);<\/script></body></html>`);w.document.close();}
function imprimirRecibo(encomienda) {
    apiFlujo('documento_emitir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo:'recibo',encomienda_id:encomienda.id})}).catch(()=>{});
    const w = window.open('', '_blank', 'width=1200,height=850');
    if (!w) {
        mostrarAlerta('warning', 'El navegador bloqueó la ventana del recibo. Permita las ventanas emergentes.');
        return;
    }

    const texto = valor => escaparHtml(valor || '');
    const fechaRegistro = encomienda.fecha_registro ? new Date(String(encomienda.fecha_registro).replace(' ', 'T')) : new Date();
    const fecha = Number.isNaN(fechaRegistro.getTime())
        ? texto(encomienda.fecha_registro)
        : fechaRegistro.toLocaleDateString('es-GT') + ' ' + fechaRegistro.toLocaleTimeString('es-GT', {hour:'2-digit', minute:'2-digit'});
    const categoria = String(encomienda.categoria || 'otros').toLowerCase();
    const marca = valor => categoria === valor ? '<span class="marca">X</span>' : '';
    const marcaOtros = ['documentos', 'joyas', 'ropa'].includes(categoria) ? '' : '<span class="marca">X</span>';
    const pesoLibras = (Number(encomienda.peso_kg || 0) * 2.2046226218).toFixed(2);
    const pagado = String(encomienda.estado_pago || '').toLowerCase() === 'pagado' || Number(encomienda.pagado) === 1;
    const moneda = encomienda.moneda === 'USD' ? '$' : 'Q';
    const total = Number(encomienda.costo_quetzales || 0).toFixed(2);
    const oficina = texto(encomienda.oficina_origen || usuarioActual?.sucursal || 'JoyaExpress');
    const direccionRemitente = [encomienda.remitente_direccion, encomienda.remitente_pais].filter(Boolean).join(', ');
    const direccionDestinatario = [encomienda.destinatario_direccion, encomienda.destinatario_pais].filter(Boolean).join(', ');

    w.document.write(`<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>Recibo ${texto(encomienda.tracking_id)}</title>
    <style>
        *{box-sizing:border-box}
        body{margin:0;background:#ececec;color:#000;font-family:Arial,Helvetica,sans-serif}
        .acciones{width:1120px;max-width:calc(100% - 24px);margin:14px auto;display:flex;justify-content:flex-end;gap:8px}
        .acciones button{border:0;border-radius:7px;padding:10px 18px;font-weight:700;cursor:pointer}
        .imprimir{background:#111;color:#fff}.cerrar{background:#d6d6d6;color:#111}
        .hoja{width:1120px;min-height:680px;margin:0 auto 22px;background:#fff;padding:22px 28px 16px}
        .recibo{border:4px solid #000;border-radius:28px 28px 24px 24px;overflow:hidden}
        .cabecera{height:174px;display:grid;grid-template-columns:29% 35% 36%}
        .marca-visual{display:flex;align-items:center;justify-content:center;gap:4px;overflow:hidden}
        .avion{font-size:88px;line-height:1;transform:rotate(-7deg);filter:grayscale(1)}
        .paquete{font-size:28px;margin-left:-69px;margin-top:-53px;background:#fff;border:3px solid #000;border-radius:50%;width:48px;height:48px;display:flex;align-items:center;justify-content:center}
        .empresa{display:flex;flex-direction:column;justify-content:center;text-align:center;padding:8px}
        .empresa h1{font-size:39px;line-height:1;margin:0 0 5px;font-weight:900;letter-spacing:1px}
        .empresa h2{font-size:20px;margin:0 0 7px;font-weight:800}
        .empresa p{font-size:18px;line-height:1.35;margin:0}
        .control{border-left:4px solid #000;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:42px 66px 34px 32px}
        .control .titulo{background:#000;color:#fff;text-align:center;font-size:18px;padding:9px 4px}
        .control .dato{border-right:3px solid #000;border-bottom:3px solid #000;padding:8px;text-align:center;font-size:15px;font-weight:700;overflow-wrap:anywhere}
        .control .ancho{grid-column:1/3;border-right:0}
        .control .origen-titulo{grid-column:1/3;background:#000;color:#fff;text-align:center;padding:6px;font-size:16px}
        .control .origen{grid-column:1/3;padding:5px 8px;text-align:center;font-size:15px;font-weight:700}
        .barra{background:#000;color:#fff;text-align:center;font-size:20px;letter-spacing:7px;padding:7px 10px}
        .linea{min-height:42px;border-bottom:3px solid #000;padding:8px 12px;font-size:17px;display:flex;gap:8px;align-items:center}
        .linea:last-child{border-bottom:0}
        .linea b{white-space:nowrap}.linea span{font-weight:600;overflow-wrap:anywhere}
        .datos-envio{display:grid;grid-template-columns:18% 16% 16% 16% 16% 18%;border-top:0}
        .celda{min-height:92px;border-right:3px solid #000;text-align:center;display:flex;flex-direction:column}
        .celda:last-child{border-right:0}
        .celda-titulo{min-height:42px;border-bottom:3px solid #000;padding:7px 4px;font-size:16px;display:flex;align-items:center;justify-content:center}
        .celda-valor{flex:1;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;padding:5px}
        .marca{display:inline-flex;align-items:center;justify-content:center;font-size:28px;font-weight:900}
        .pago{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:auto 1fr}
        .pago > div{padding:5px 3px}
        .pago .pago-titulo{grid-column:1/3;border-bottom:3px solid #000;font-size:15px;font-weight:700}
        .pago .opcion:first-of-type{border-right:3px solid #000}
        .opcion{display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:12px}
        .casilla{width:46px;height:29px;border:2px solid #000;margin-top:4px;font-size:23px;line-height:24px;font-weight:900}
        .pie-datos{display:grid;grid-template-columns:82% 18%}
        .descripcion{border-right:3px solid #000}
        .descripcion .contenido{min-height:91px;padding:10px 12px;font-size:17px;font-weight:600;white-space:pre-wrap;overflow-wrap:anywhere}
        .total{text-align:center;display:flex;flex-direction:column}
        .total-titulo{font-size:18px;padding:8px;border-bottom:3px solid #000}
        .total-valor{flex:1;display:flex;align-items:center;justify-content:center;font-size:23px;font-weight:900}
        .nota{text-align:center;font-size:14px;font-weight:700;padding:8px 4px 0;text-transform:uppercase}
        .referencia{font-size:11px;text-align:right;margin-top:4px;color:#333}
        @page{size:landscape;margin:8mm}
        @media print{
            body{background:#fff}
            .acciones{display:none}
            .hoja{width:100%;min-height:0;margin:0;padding:0}
            .recibo{break-inside:avoid}
        }
        @media(max-width:900px){
            .hoja{transform-origin:top left}
            body{overflow-x:auto}
        }
    </style>
</head>
<body>
    <div class="acciones">
        <button class="cerrar" onclick="window.close()">Cerrar</button>
        <button class="imprimir" onclick="window.print()">Guardar PDF / Imprimir</button>
    </div>
    <main class="hoja">
        <section class="recibo">
            <header class="cabecera">
                <div class="marca-visual"><div class="avion">✈</div><div class="paquete">▣</div></div>
                <div class="empresa">
                    <h1>JOYA EXPRESS</h1>
                    <h2>GUATEMALA A ESTADOS UNIDOS</h2>
                    <p>TELS. (502) 4081-8969<br>(256) 994-8692</p>
                </div>
                <div class="control">
                    <div class="titulo">FECHA / HORA</div><div class="titulo">ENVÍO</div>
                    <div class="dato">${fecha}</div><div class="dato">${texto(encomienda.tracking_id)}</div>
                    <div class="origen-titulo">OFICINA DE ORIGEN</div>
                    <div class="origen">${oficina}</div>
                </div>
            </header>

            <div class="barra">REMITENTE</div>
            <div class="linea"><b>Nombre:</b><span>${texto(encomienda.remitente_nombre)} · Tel. ${texto(encomienda.remitente_telefono)}</span></div>
            <div class="linea"><b>Dirección:</b><span>${texto(direccionRemitente)}</span></div>

            <div class="barra">DESTINATARIO</div>
            <div class="linea"><b>Nombre:</b><span>${texto(encomienda.destinatario_nombre)} · Tel. ${texto(encomienda.destinatario_telefono)}</span></div>
            <div class="linea"><b>Dirección:</b><span>${texto(direccionDestinatario)}</span></div>

            <div class="datos-envio">
                <div class="celda"><div class="celda-titulo">Ropa / Paquete</div><div class="celda-valor">${categoria === 'ropa' ? '<span class="marca">X</span>' : ''}</div></div>
                <div class="celda"><div class="celda-titulo">Peso en Libras</div><div class="celda-valor">${pesoLibras} lb</div></div>
                <div class="celda"><div class="celda-titulo">Joyas</div><div class="celda-valor">${marca('joyas')}</div></div>
                <div class="celda"><div class="celda-titulo">Documentos</div><div class="celda-valor">${marca('documentos')}</div></div>
                <div class="celda"><div class="celda-titulo">Otros</div><div class="celda-valor">${marcaOtros}</div></div>
                <div class="celda pago">
                    <div class="pago-titulo">ESTADO DE PAGO</div>
                    <div class="opcion">PAGADO<div class="casilla">${pagado ? 'X' : ''}</div></div>
                    <div class="opcion">POR COBRAR<div class="casilla">${pagado ? '' : 'X'}</div></div>
                </div>
            </div>

            <div class="pie-datos">
                <div class="descripcion">
                    <div class="barra">DESCRIPCIÓN DEL CONTENIDO</div>
                    <div class="contenido">${texto(encomienda.descripcion_items)}${encomienda.cantidad_items ? `<br><small>Cantidad de artículos: ${texto(encomienda.cantidad_items)}</small>` : ''}</div>
                </div>
                <div class="total"><div class="total-titulo">TOTAL</div><div class="total-valor">${moneda} ${total}</div></div>
            </div>
        </section>
        <div class="nota">“A nuestros clientes les solicitamos leer al reverso de este recibo las condiciones e instrucciones”</div>
        <div class="referencia">Tracking: ${texto(encomienda.tracking_id)}</div>
    </main>
</body>
</html>`);
    w.document.close();
}
async function imprimirManifiesto(maletaId){try{const r=await fetch(`${API_URL}/maletas.php?accion=manifiesto&maleta_id=${maletaId}`);const d=await r.json();if(!d.exito)throw new Error(d.mensaje);apiFlujo('documento_emitir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo:'manifiesto',maleta_id:maletaId})}).catch(()=>{});const x=d.datos,w=window.open('','_blank');w.document.write(`<html><head><title>Manifiesto ${x.maleta.id_maleta}</title><style>body{font-family:Arial;padding:30px}.acciones{margin-bottom:20px}@media print{.acciones{display:none}}table{width:100%;border-collapse:collapse}th,td{border:1px solid #aaa;padding:6px}</style></head><body><div class="acciones"><button onclick="window.print()">Guardar PDF / Imprimir</button></div><h1>Manifiesto JoyaExpress</h1><p><b>Maleta:</b> ${x.maleta.id_maleta} | <b>Vuelo/envío:</b> ${escaparHtml(x.maleta.vuelo_envio||'')} | <b>Destino:</b> ${x.maleta.pais_destino} | <b>Peso:</b> ${x.peso_total} kg</p><table><thead><tr><th>Tracking</th><th>Destinatario</th><th>Peso</th></tr></thead><tbody>${x.paquetes.map(e=>`<tr><td>${e.tracking_id}</td><td>${escaparHtml(e.destinatario_nombre)}</td><td>${e.peso_kg}</td></tr>`).join('')}</tbody></table></body></html>`);w.document.close();}catch(e){mostrarAlerta('danger',e.message);}}

async function anularEncomienda(id){const motivo=prompt('Motivo de anulación:');if(!motivo)return;try{await apiOperaciones('anular_encomienda',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({encomienda_id:id,motivo})});buscarEncomiendas();cargarEstadisticas();mostrarAlerta('success','Encomienda anulada');}catch(e){mostrarAlerta('danger',e.message);}}

function guardarEncomiendaPendiente(datos) {
    const pendientes=JSON.parse(localStorage.getItem('joyaexpress_pendientes')||'[]');
    pendientes.push({id_local:crypto.randomUUID?.()||Date.now(),fecha:new Date().toISOString(),datos});
    localStorage.setItem('joyaexpress_pendientes',JSON.stringify(pendientes));actualizarAvisoPendientes();
    mostrarAlerta('warning','Sin conexión: la encomienda quedó guardada localmente para sincronizarla después.');
}
function actualizarAvisoPendientes(){const n=JSON.parse(localStorage.getItem('joyaexpress_pendientes')||'[]').length;const a=document.getElementById('aviso-contingencia');if(a){a.style.display=n?'block':'none';document.getElementById('cantidad-pendientes').textContent=n;}}
async function sincronizarPendientes(){const pendientes=JSON.parse(localStorage.getItem('joyaexpress_pendientes')||'[]'),fallidos=[];for(const p of pendientes){try{const r=await fetch(`${API_URL}/encomiendas.php?accion=crear`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p.datos)});const d=await r.json();if(!d.exito)throw new Error(d.mensaje);}catch{fallidos.push(p);}}localStorage.setItem('joyaexpress_pendientes',JSON.stringify(fallidos));actualizarAvisoPendientes();mostrarAlerta(fallidos.length?'warning':'success',fallidos.length?`${fallidos.length} registros siguen pendientes`:'Registros sincronizados');buscarEncomiendas();cargarEstadisticas();}
function exportarTablaCSV(id,nombre='reporte.csv'){const tablas=[...document.querySelectorAll(`#${id} table`)];if(!tablas.length)return mostrarAlerta('warning','No hay tablas para exportar');const lineas=[];tablas.forEach((tabla,i)=>{const titulo=tabla.closest('.card')?.querySelector('h5')?.innerText||`Reporte ${i+1}`;lineas.push('"'+titulo.replaceAll('"','""')+'"');lineas.push(...[...tabla.rows].map(f=>[...f.cells].map(c=>'"'+c.innerText.replaceAll('"','""')+'"').join(',')));lineas.push('');});const blob=new Blob(['\ufeff'+lineas.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=nombre;a.click();URL.revokeObjectURL(a.href);}

async function asignarTrackingEscaneado(){
    const tracking=document.getElementById('scanner-tracking').value.trim(),maletaId=Number(document.getElementById('scanner-maleta').value);
    if(!tracking||!maletaId)return mostrarAlerta('warning','Seleccione una maleta e ingrese el tracking');
    try{const r=await fetch(`${API_URL}/encomiendas.php?accion=obtener&tracking_id=${encodeURIComponent(tracking)}`);const d=await r.json();if(!d.exito)throw new Error(d.mensaje);const a=await fetch(`${API_URL}/maletas.php?accion=asignar_encomienda`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({maleta_id:maletaId,encomienda_id:d.datos.id})});const x=await a.json();if(!x.exito)throw new Error(x.mensaje);document.getElementById('scanner-tracking').value='';cargarMaletasAbiertas();buscarEncomiendas();mostrarAlerta('success','Paquete agregado mediante tracking/QR');}catch(e){mostrarAlerta('danger',e.message);}
}
async function iniciarLectorCamara(){
    if(!('BarcodeDetector' in window))return mostrarAlerta('warning','Este navegador no admite lectura por cámara. Use un lector USB o escriba el tracking.');
    const video=document.getElementById('scanner-video');try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=stream;video.style.display='block';await video.play();const detector=new BarcodeDetector({formats:['qr_code','code_128']});const timer=setInterval(async()=>{const codigos=await detector.detect(video);if(codigos.length){clearInterval(timer);stream.getTracks().forEach(t=>t.stop());video.style.display='none';document.getElementById('scanner-tracking').value=codigos[0].rawValue;asignarTrackingEscaneado();}},500);setTimeout(()=>{clearInterval(timer);stream.getTracks().forEach(t=>t.stop());video.style.display='none';},30000);}catch(e){mostrarAlerta('danger','No se pudo abrir la cámara: '+e.message);}
}

async function cargarSucursales(){try{const d=await apiOperaciones('sucursales_listar');document.getElementById('lista-sucursales').innerHTML=`<table class="table"><thead><tr><th>Nombre</th><th>País</th><th>Dirección</th><th>Activa</th><th></th></tr></thead><tbody>${d.map(s=>`<tr><td>${escaparHtml(s.nombre)}</td><td>${s.pais}</td><td>${escaparHtml(s.direccion||'')}</td><td>${Number(s.activa)?'Sí':'No'}</td><td><button class="btn btn-sm btn-primary" onclick='editarSucursal(${JSON.stringify(s)})'>Editar</button></td></tr>`).join('')}</tbody></table>`;}catch(e){mostrarAlerta('danger',e.message);}}
function editarSucursal(s=null){const x=s||{};mostrarModalDetalles('Sucursal',`<form id="form-sucursal"><input type="hidden" name="id" value="${x.id||''}"><input class="form-control mb-2" name="nombre" required placeholder="Nombre" value="${escaparHtml(x.nombre||'')}"><select class="form-select mb-2" name="pais">${opcionPaises(x.pais)}</select><textarea class="form-control mb-2" name="direccion" placeholder="Dirección">${escaparHtml(x.direccion||'')}</textarea><div class="form-check mb-3"><input class="form-check-input" name="activa" type="checkbox" ${x.activa===undefined||Number(x.activa)?'checked':''}><label>Activa</label></div><button class="btn btn-primary">Guardar</button></form>`);document.getElementById('form-sucursal').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));d.id=Number(d.id||0);d.activa=f.elements.activa.checked;try{await apiOperaciones('sucursal_guardar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();cargarSucursales();mostrarAlerta('success','Sucursal guardada');}catch(err){mostrarAlerta('danger',err.message);}};}

cargarRutas=async function(){try{const [rutas,catalogos]=await Promise.all([apiOperaciones('rutas_listar'),apiOperaciones('catalogos')]);document.getElementById('ruta-mensajero').innerHTML=catalogos.mensajeros.map(m=>`<option value="${m.id}">${m.nombre}</option>`).join('');document.getElementById('form-ruta').onsubmit=guardarRuta;document.getElementById('lista-rutas').innerHTML=rutas.length?`<table class="table"><thead><tr><th>Código</th><th>Ruta</th><th>Mensajero</th><th>Fecha</th><th>Estado</th><th>Paquetes</th><th></th></tr></thead><tbody>${rutas.map(r=>`<tr><td>${r.codigo}</td><td>${r.nombre_ruta}</td><td>${r.mensajero_nombre}</td><td>${r.fecha_ruta}</td><td>${r.estado}</td><td>${r.paquetes}</td><td><button class="btn btn-sm btn-primary" onclick="verPaquetesRuta(${r.id},'${r.codigo}')">Ver</button></td></tr>`).join('')}</tbody></table>`:'<div class="alert alert-info">No hay rutas.</div>';}catch(e){mostrarAlerta('danger',e.message);}};
async function verPaquetesRuta(id,codigo){try{const d=await apiOperaciones(`ruta_paquetes&ruta_id=${id}`);const filas=d.map(e=>`<tr><td>${e.tracking_id}</td><td>${escaparHtml(e.destinatario_nombre)}</td><td>${e.estado}</td></tr>`).join('');mostrarModalDetalles(`Paquetes de ${codigo}`,filas?`<table class="table"><thead><tr><th>Tracking</th><th>Destinatario</th><th>Estado</th></tr></thead><tbody>${filas}</tbody></table>`:'<div class="alert alert-info">Ruta sin paquetes</div>');}catch(e){mostrarAlerta('danger',e.message);}}

cargarReportesAvanzados=async function(){try{const cont=document.getElementById('control-reportes')||document.getElementById('reportes-avanzados');if(!cont)return;const hoy=new Date().toISOString().slice(0,10),inicio=hoy.slice(0,8)+'01';if(!document.getElementById('reporte-desde'))cont.innerHTML=`<div class="card mb-3"><div class="card-body"><div class="row g-2"><div class="col-md-3"><label>Desde</label><input id="reporte-desde" type="date" class="form-control" value="${inicio}"></div><div class="col-md-3"><label>Hasta</label><input id="reporte-hasta" type="date" class="form-control" value="${hoy}"></div><div class="col-md-2"><label>SLA horas</label><input id="reporte-sla" type="number" class="form-control" value="72"></div><div class="col-md-4 d-flex align-items-end gap-2"><button class="btn btn-primary" onclick="cargarReportesAvanzados()">Consultar</button><button class="btn btn-success" onclick="exportarTablaCSV('resultado-reportes','reporte-completo.csv')">Excel/CSV</button><button class="btn btn-secondary" onclick="window.print()">PDF/Imprimir</button></div></div></div></div><div id="resultado-reportes"></div>`;const desde=document.getElementById('reporte-desde').value,hasta=document.getElementById('reporte-hasta').value,sla=document.getElementById('reporte-sla').value,d=await apiOperaciones(`reportes_completos&desde=${desde}&hasta=${hasta}&sla_horas=${sla}`);const tabla=(t,f,c)=>`<div class="card mb-3"><div class="card-body"><h5>${t}</h5><table class="table table-sm"><thead><tr>${c.map(x=>`<th>${x[1]}</th>`).join('')}</tr></thead><tbody>${(f||[]).map(r=>`<tr>${c.map(x=>`<td>${r[x[0]]??0}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;document.getElementById('resultado-reportes').innerHTML=`<div class="alert alert-info"><b>SLA:</b> ${d.slaDatos.porcentaje}% dentro de ${d.sla} horas · <b>Trazabilidad:</b> ${d.trazabilidadCompleta.porcentaje||0}% · <b>Cierre de maleta:</b> ${d.controlMaletas.minutos_promedio||0} min.</div>`+tabla('Por sucursal',d.porSucursal,[['sucursal','Sucursal'],['cantidad','Cantidad']])+tabla('Tiempos por etapa',d.tiemposEtapa,[['estado','Etapa'],['promedio_horas','Horas promedio']])+tabla('Métricas de operación',d.metricas,[['tipo','Operación'],['promedio_segundos','Promedio segundos'],['mediciones','Mediciones']])+tabla('Trabajo en proceso (WIP)',d.wip,[['estado','Estado'],['cantidad','Cantidad']])+tabla('Productividad',d.productividad,[['nombre','Empleado'],['fecha','Fecha'],['cantidad','Cantidad']])+tabla('Incidencias',d.incidencias,[['tipo','Tipo'],['cantidad','Cantidad']])+tabla('Seguridad',d.seguridad,[['accion','Evento'],['cantidad','Cantidad']])+tabla('Ingresos',d.ingresos,[['remitente_pais','Origen'],['destinatario_pais','Destino'],['envios','Envíos'],['ingresos','Q']])+tabla('Maletas',d.maletas,[['pais_destino','Destino'],['cantidad','Cantidad'],['peso_promedio','Peso promedio']]);}catch(e){mostrarAlerta('danger',e.message);}};

imprimirEtiqueta=function(encomienda){apiFlujo('documento_emitir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo:'etiqueta',encomienda_id:encomienda.id})}).catch(()=>{});const w=window.open('','_blank','width=650,height=800');w.document.write(`<html><head><title>Etiqueta ${encomienda.tracking_id}</title><style>body{font-family:Arial;text-align:center;padding:25px}.etiqueta{border:3px solid #000;padding:20px}#qr{margin:15px auto;width:180px}svg{max-width:100%}</style></head><body><div class="etiqueta"><h1>JoyaExpress</h1><div id="qr"></div><svg id="barcode"></svg><h2>${encomienda.tracking_id}</h2><p><b>${escaparHtml(encomienda.destinatario_nombre)}</b><br>${encomienda.destinatario_pais}<br>${encomienda.peso_kg} kg</p></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script><script>new QRCode(document.getElementById('qr'),{text:'${encomienda.tracking_id}',width:180,height:180});JsBarcode('#barcode','${encomienda.tracking_id}',{format:'CODE128',width:2,height:60});setTimeout(()=>window.print(),800);<\/script></body></html>`);w.document.close();};

function plantillaRecepcionDestino(){return `<h2><i class="fas fa-clipboard-check"></i> Recepción en destino</h2><p class="text-muted">Escanee la maleta y luego cada paquete para compararlos con el manifiesto.</p><div class="card mb-3"><div class="card-body"><div class="row g-2"><div class="col-md-8"><input id="recepcion-codigo-maleta" class="form-control" placeholder="Código QR o ID de la maleta"></div><div class="col-md-4"><button class="btn btn-primary w-100" onclick="iniciarRecepcionDestino()">Iniciar verificación</button></div></div></div></div><div id="panel-recepcion-activa"></div><div id="lista-recepciones-destino"></div>`;}
function plantillaRetiros(){return `<h2><i class="fas fa-store"></i> Retiros en sucursal</h2><p class="text-muted">Paquetes listos para entregar en la sucursal autorizada.</p><div id="lista-retiros"></div>`;}
function plantillaNotificaciones(){return `<h2><i class="fas fa-envelope"></i> Notificaciones</h2><div class="d-flex gap-2 mb-3"><select id="filtro-notificacion" class="form-select" style="max-width:220px" onchange="cargarNotificaciones()"><option value="">Todas</option><option value="pendiente">Pendientes</option><option value="enviada">Enviadas</option><option value="fallida">Fallidas</option></select><button class="btn btn-primary" onclick="procesarNotificaciones()">Procesar cola</button></div><div id="lista-notificaciones"></div>`;}

async function prepararSucursalesRetiro(){
    const pais=document.querySelector('[name="destinatario_pais"]'),grupo=document.getElementById('grupo-sucursal-retiro'),select=document.getElementById('sucursal-retiro');if(!pais||!grupo||!select)return;
    let sucursales=[];try{sucursales=(await apiOperaciones('sucursales_listar')).filter(s=>Number(s.activa));}catch{return;}
    const actualizar=()=>{const retiro=pais.value&&pais.value!=='USA';grupo.style.display=retiro?'block':'none';select.required=retiro;select.disabled=!retiro;select.innerHTML='<option value="">Seleccionar sucursal</option>'+sucursales.filter(s=>s.pais===pais.value).map(s=>`<option value="${s.id}">${escaparHtml(s.nombre)}</option>`).join('');const tipo=document.querySelector('[name="tipo_entrega"]');if(tipo){tipo.value=retiro?'retiro_sucursal':'entrega_domicilio';tipo.disabled=true;}};
    pais.addEventListener('change',actualizar);actualizar();
}

async function cargarRecepcionesDestino(){try{const d=await apiFlujo('recepcion_maletas');document.getElementById('lista-recepciones-destino').innerHTML=d.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Maleta</th><th>Destino</th><th>Estado</th><th>Verificados</th><th></th></tr></thead><tbody>${d.map(m=>`<tr><td>${m.id_maleta}</td><td>${m.pais_destino}</td><td>${m.recepcion_estado||m.estado}</td><td>${m.escaneados}/${m.esperados}</td><td>${m.recepcion_estado==='en_verificacion'?`<button class="btn btn-sm btn-primary" onclick="abrirRecepcion(${m.recepcion_id})">Continuar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="alert alert-info">No hay maletas enviadas pendientes de recepción.</div>';}catch(e){mostrarAlerta('danger',e.message);}}
async function iniciarRecepcionDestino(){const codigo=document.getElementById('recepcion-codigo-maleta').value.trim();if(!codigo)return mostrarAlerta('warning','Ingrese o escanee el código de la maleta');try{const d=await apiFlujo('recepcion_iniciar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({codigo})});abrirRecepcion(d.recepcion_id);}catch(e){mostrarAlerta('danger',e.message);}}
async function abrirRecepcion(id){try{const d=await apiFlujo(`recepcion_detalle&recepcion_id=${id}`),recibidos=d.paquetes.filter(p=>Number(p.recibido)).length;document.getElementById('panel-recepcion-activa').innerHTML=`<div class="card mb-4"><div class="card-body"><h4>${d.recepcion.id_maleta}</h4><div class="progress mb-3" style="height:24px"><div class="progress-bar" style="width:${d.paquetes.length?100*recibidos/d.paquetes.length:0}%">${recibidos}/${d.paquetes.length}</div></div><div class="row g-2"><div class="col-md-7"><input id="recepcion-tracking" class="form-control form-control-lg" placeholder="Escanee el tracking" onkeydown="if(event.key==='Enter'){event.preventDefault();escanearRecepcion(${id})}"></div><div class="col-md-3"><button class="btn btn-primary btn-lg w-100" onclick="escanearRecepcion(${id})">Verificar</button></div><div class="col-md-2"><button class="btn btn-outline-primary btn-lg w-100" onclick="iniciarCamaraRecepcion(${id})"><i class="fas fa-camera"></i></button></div></div><video id="recepcion-video" class="mt-2 w-100" style="display:none;max-height:280px" playsinline></video><div class="mt-3 row g-2">${d.paquetes.map(p=>`<div class="col-md-4"><div class="alert ${Number(p.recibido)?'alert-success':'alert-secondary'} py-2 mb-0"><i class="fas ${Number(p.recibido)?'fa-check':'fa-clock'}"></i> ${p.tracking_id}<br><small>${escaparHtml(p.destinatario_nombre)}</small></div></div>`).join('')}</div>${d.diferencias.length?`<div class="alert alert-danger mt-3"><b>Diferencias:</b> ${d.diferencias.map(x=>`${x.tracking_escaneado} (${x.resultado})`).join(', ')}</div>`:''}<textarea id="recepcion-observaciones" class="form-control mt-3" placeholder="Observaciones de recepción"></textarea><button class="btn btn-success mt-3" onclick="finalizarRecepcion(${id})">Finalizar recepción</button></div></div>`;document.getElementById('recepcion-tracking').focus();}catch(e){mostrarAlerta('danger',e.message);}}
async function escanearRecepcion(id){const input=document.getElementById('recepcion-tracking'),tracking=input.value.trim();if(!tracking)return;try{await apiFlujo('recepcion_escanear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recepcion_id:id,tracking})});mostrarAlerta('success','Paquete verificado');input.value='';abrirRecepcion(id);}catch(e){mostrarAlerta('danger',e.message);input.select();}}
async function iniciarCamaraRecepcion(id){if(!('BarcodeDetector'in window))return mostrarAlerta('warning','Este navegador no admite lectura por cámara; use lector USB.');const video=document.getElementById('recepcion-video');try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=stream;video.style.display='block';await video.play();const detector=new BarcodeDetector({formats:['qr_code','code_128']});const timer=setInterval(async()=>{const codigos=await detector.detect(video);if(codigos.length){clearInterval(timer);stream.getTracks().forEach(t=>t.stop());document.getElementById('recepcion-tracking').value=codigos[0].rawValue;escanearRecepcion(id);}},400);setTimeout(()=>{clearInterval(timer);stream.getTracks().forEach(t=>t.stop());if(video)video.style.display='none';},30000);}catch(e){mostrarAlerta('danger','No se pudo abrir la cámara: '+e.message);}}
async function finalizarRecepcion(id,confirmar=false){try{const observaciones=document.getElementById('recepcion-observaciones')?.value||'';await apiFlujo('recepcion_finalizar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recepcion_id:id,observaciones,confirmar_diferencias:confirmar})});mostrarAlerta('success','Recepción finalizada y paquetes actualizados');document.getElementById('panel-recepcion-activa').innerHTML='';cargarRecepcionesDestino();cargarEstadisticas();}catch(e){if(e.status===409&&confirm(`Hay ${e.datos?.faltantes?.length||0} faltantes y ${e.datos?.no_manifestados||0} no manifestados. ¿Finalizar y crear incidencias?`))return finalizarRecepcion(id,true);mostrarAlerta('danger',e.message);}}

async function cargarRetiros(){try{const d=await apiFlujo('retiros_listar');document.getElementById('lista-retiros').innerHTML=d.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Tracking</th><th>Destinatario</th><th>Teléfono</th><th>Sucursal</th><th></th></tr></thead><tbody>${d.map(e=>`<tr><td>${e.tracking_id}</td><td>${escaparHtml(e.destinatario_nombre)}</td><td>${escaparHtml(e.destinatario_telefono)}</td><td>${escaparHtml(e.sucursal_retiro)}</td><td><button class="btn btn-success btn-sm" onclick="abrirRetiro(${e.id},'${e.tracking_id}')">Entregar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="alert alert-info">No hay paquetes listos para retiro en esta sucursal.</div>';}catch(e){mostrarAlerta('danger',e.message);}}
function abrirRetiro(id,tracking){mostrarModalDetalles(`Confirmar retiro ${tracking}`,`<form id="form-retiro"><input class="form-control mb-2" name="receptor_nombre" required placeholder="Nombre completo de quien retira"><input class="form-control mb-2" name="documento_receptor" required placeholder="DPI, pasaporte o identificación"><textarea class="form-control mb-3" name="observaciones" placeholder="Observaciones"></textarea><button class="btn btn-success">Confirmar y generar constancia</button></form>`);document.getElementById('form-retiro').onsubmit=async ev=>{ev.preventDefault();const datos=Object.fromEntries(new FormData(ev.target));datos.encomienda_id=id;try{await apiFlujo('retiro_confirmar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(datos)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();imprimirConstanciaRetiro(id,tracking,datos);mostrarAlerta('success','Retiro confirmado');cargarRetiros();buscarEncomiendas();}catch(e){mostrarAlerta('danger',e.message);}};}
function imprimirConstanciaRetiro(id,tracking,datos){apiFlujo('documento_emitir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo:'constancia_retiro',encomienda_id:id})}).catch(()=>{});const w=window.open('','_blank','width=700,height=600');if(!w)return;w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Constancia ${tracking}</title><style>body{font-family:Arial;padding:45px}.doc{border:3px solid #111;border-radius:16px;padding:30px}h1{text-align:center}.firma{margin-top:70px;border-top:1px solid;width:280px;text-align:center}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Guardar PDF / Imprimir</button><div class="doc"><h1>JOYA EXPRESS</h1><h2>Constancia de retiro</h2><p><b>Tracking:</b> ${tracking}</p><p><b>Fecha:</b> ${new Date().toLocaleString('es-GT')}</p><p><b>Recibido por:</b> ${escaparHtml(datos.receptor_nombre)}</p><p><b>Documento:</b> ${escaparHtml(datos.documento_receptor)}</p><p><b>Observaciones:</b> ${escaparHtml(datos.observaciones||'')}</p><div class="firma">Firma de quien recibe</div></div></body></html>`);w.document.close();}

async function cargarNotificaciones(){try{const estado=document.getElementById('filtro-notificacion')?.value||'',r=await fetch(`/joyaexpress-system/backend/api/notificaciones.php?accion=listar&estado=${estado}`,{cache:'no-store'}),x=await r.json();if(!x.exito)throw new Error(x.mensaje);document.getElementById('lista-notificaciones').innerHTML=`<div class="table-responsive"><table class="table"><thead><tr><th>Fecha</th><th>Tracking</th><th>Correo</th><th>Estado</th><th>Intentos</th><th>Error</th></tr></thead><tbody>${x.datos.map(n=>`<tr><td>${n.fecha_creacion}</td><td>${n.tracking_id}</td><td>${escaparHtml(n.destinatario_email||'Sin correo')}</td><td>${n.estado}</td><td>${n.intentos}</td><td>${escaparHtml(n.ultimo_error||'')}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){mostrarAlerta('danger',e.message);}}
async function procesarNotificaciones(){try{const r=await fetch('/joyaexpress-system/backend/api/notificaciones.php?accion=procesar',{method:'POST'}),d=await r.json();if(!d.exito)throw new Error(d.mensaje);mostrarAlerta(d.datos.fallidas?'warning':'success',`Enviadas: ${d.datos.enviadas}. Fallidas: ${d.datos.fallidas}.`);cargarNotificaciones();}catch(e){mostrarAlerta('danger',e.message);}}
function registrarMetricaOperacion(tipo,duracion_ms,exitoso=true){apiFlujo('metrica',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo,duracion_ms,exitoso})}).catch(()=>{});}

cargarRutas=async function(){try{const [rutas,catalogos]=await Promise.all([apiOperaciones('rutas_listar'),apiOperaciones('catalogos')]),formRuta=document.getElementById('form-ruta'),selector=document.getElementById('ruta-mensajero');if(selector)selector.innerHTML=catalogos.mensajeros.map(m=>`<option value="${m.id}">${m.nombre}</option>`).join('');if(formRuta){formRuta.onsubmit=guardarRuta;if(!tieneRol(['admin','supervisor','bodega']))formRuta.closest('.card').style.display='none';}document.getElementById('lista-rutas').innerHTML=rutas.length?`<div class="table-responsive"><table class="table"><thead><tr><th>Código</th><th>Ruta</th><th>Mensajero</th><th>Fecha</th><th>Estado</th><th>Paquetes</th><th>Acciones</th></tr></thead><tbody>${rutas.map(r=>`<tr><td>${r.codigo}</td><td>${escaparHtml(r.nombre_ruta)}</td><td>${escaparHtml(r.mensajero_nombre)}</td><td>${r.fecha_ruta}</td><td>${r.estado}</td><td>${r.paquetes}</td><td><button class="btn btn-sm btn-primary" onclick="verPaquetesRuta(${r.id},'${r.codigo}')">Ver</button> ${r.estado==='planificada'?`<button class="btn btn-sm btn-success" onclick="cambiarEstadoRuta(${r.id},'en_ruta')">Iniciar</button>`:''} ${r.estado==='en_ruta'?`<button class="btn btn-sm btn-success" onclick="cambiarEstadoRuta(${r.id},'finalizada')">Finalizar</button>`:''} ${!['finalizada','cancelada'].includes(r.estado)&&tieneRol(['admin','supervisor','bodega'])?`<button class="btn btn-sm btn-outline-danger" onclick="cambiarEstadoRuta(${r.id},'cancelada')">Cancelar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="alert alert-info">No hay rutas.</div>';}catch(e){mostrarAlerta('danger',e.message);}};
async function cambiarEstadoRuta(id,estado){let motivo='';if(estado==='cancelada'&&!(motivo=prompt('Motivo de cancelación:')||''))return;try{await apiFlujo('ruta_estado',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({ruta_id:id,estado,motivo})});mostrarAlerta('success','Ruta actualizada');cargarRutas();}catch(e){mostrarAlerta('danger',e.message);}}
verPaquetesRuta=async function(id,codigo){try{const d=await apiOperaciones(`ruta_paquetes&ruta_id=${id}`);const filas=d.map(e=>`<tr><td>${e.tracking_id}</td><td>${escaparHtml(e.destinatario_nombre)}</td><td>${e.estado_entrega||e.estado}${e.motivo_fallo?`<br><small>${escaparHtml(e.motivo_fallo)}</small>`:''}</td><td>${e.estado==='en_ruta'&&e.estado_entrega!=='fallida'?`<button class="btn btn-sm btn-success" onclick="abrirConfirmarEntrega(${e.id},'entrega_domicilio')">Entregar</button> <button class="btn btn-sm btn-outline-danger" onclick="registrarEntregaFallida(${e.id})">Fallida</button>`:''}${e.estado_entrega==='fallida'?`<button class="btn btn-sm btn-warning" onclick="asignarARuta(${e.id})">Reasignar</button>`:''}</td></tr>`).join('');mostrarModalDetalles(`Paquetes de ${codigo}`,filas?`<table class="table"><thead><tr><th>Tracking</th><th>Destinatario</th><th>Resultado</th><th></th></tr></thead><tbody>${filas}</tbody></table>`:'<div class="alert alert-info">Ruta sin paquetes</div>');}catch(e){mostrarAlerta('danger',e.message);}};
async function registrarEntregaFallida(id){const motivo=prompt('Motivo de la entrega fallida:');if(!motivo)return;try{await apiFlujo('entrega_fallida',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({encomienda_id:id,motivo})});mostrarAlerta('warning','Intento fallido registrado');}catch(e){mostrarAlerta('danger',e.message);}}
async function verEvidenciasEntrega(id){try{const d=await apiFlujo(`evidencias&encomienda_id=${id}`);mostrarModalDetalles('Evidencia de entrega',d.length?d.map(x=>`<div class="card mb-2"><div class="card-body"><b>Receptor:</b> ${escaparHtml(x.receptor_nombre)}<br><b>Documento:</b> ${escaparHtml(x.documento_receptor||'')}<br><b>Fecha:</b> ${x.fecha_entrega}<br><b>Responsable:</b> ${escaparHtml(x.entregado_por_nombre)}<br><b>Observaciones:</b> ${escaparHtml(x.observaciones||'')}${x.foto_ruta?`<br><a target="_blank" href="/joyaexpress-system/${x.foto_ruta}">Ver fotografía</a>`:''}${x.firma_ruta?` · <a target="_blank" href="/joyaexpress-system/${x.firma_ruta}">Ver firma</a>`:''}</div></div>`).join(''):'<div class="alert alert-info">No hay evidencia registrada.</div>');}catch(e){mostrarAlerta('danger',e.message);}}
editarUsuario=async function(u=null){const x=u||{};try{const catalogos=await apiOperaciones('catalogos'),opcionesSucursal=catalogos.sucursales.filter(s=>Number(s.activa)).map(s=>`<option value="${s.id}" ${Number(s.id)===Number(x.sucursal_id)?'selected':''}>${escaparHtml(s.nombre)} — ${s.pais}</option>`).join('');const html=`<form id="form-usuario"><input type="hidden" name="id" value="${x.id||''}"><input class="form-control mb-2" name="nombre" required placeholder="Nombre" value="${escaparHtml(x.nombre||'')}"><input class="form-control mb-2" type="email" name="email" required placeholder="Email" value="${escaparHtml(x.email||'')}"><select class="form-select mb-2" name="rol">${['admin','supervisor','bodega','recepcion','entrega'].map(r=>`<option ${r===x.rol?'selected':''}>${r}</option>`)}</select><select class="form-select mb-2" name="sucursal_id" required><option value="">Seleccione sucursal</option>${opcionesSucursal}</select>${u?'':`<input class="form-control mb-2" type="password" name="password" minlength="8" required placeholder="Contraseña inicial">`}<select class="form-select mb-3" name="estado"><option value="activo">Activo</option><option value="inactivo" ${x.estado==='inactivo'?'selected':''}>Inactivo</option><option value="bloqueado" ${x.estado==='bloqueado'?'selected':''}>Bloqueado</option></select><button class="btn btn-primary">Guardar</button></form>`;mostrarModalDetalles(u?'Editar usuario':'Nuevo usuario',html);document.getElementById('form-usuario').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.id=Number(d.id||0);d.sucursal_id=Number(d.sucursal_id);try{await apiOperaciones('usuario_guardar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});bootstrap.Modal.getInstance(document.querySelector('.modal.show')).hide();cargarUsuarios();mostrarAlerta('success','Usuario guardado');}catch(err){mostrarAlerta('danger',err.message);}};}catch(e){mostrarAlerta('danger',e.message);}};
